        "rich": [
          "<h4 class=\"hf-rich--heading4\">Figure styles</h4>",
          "<p class=\"hf-rich--body\">Proportional figures (default) and tabular figures</p>",
          "<h4 class=\"hf-rich--heading4\">Superscript and subscript</h4>",
          "<p class=\"hf-rich--body\">Raised and lowered numbers</p>",
          "<h4 class=\"hf-rich--heading4\">Case-sensitive forms</h4>",
          "<p class=\"hf-rich--body\">Punctuation that adapts to capital letters</p>",
          "<h4 class=\"hf-rich--heading4\">Stylistic variant</h4>",
          "<p class=\"hf-rich--body\">Closed-form alternative for digit 4</p>"
        ],
