      "41": {
        "heading": "Where to find our fonts",
        "level": "h2"
      },
      "42": {},
      "43": {
        "rich": [
          "<p class=\"hf-rich--body\">Our Desktop and Office fonts are pre-installed on all ImmoScout24 workstations.</p><p class=\"hf-rich--body\"></p><p class=\"hf-rich--body\"><span class=\"hf-rich--bold\">If you need the font files:</span></p><p class=\"hf-rich--body\"><span class=\"hf-rich--bold\"></span></p><ul><li class=\"hf-rich--body\"><p><span></span><span><span class=\"hf-rich--bold\">Internal employees:</span> Please write in the #creative-studio Slack channel</span></p></li><li class=\"hf-rich--body\"><p><span></span><span><span class=\"hf-rich--bold\">External partners:</span> Please contact your client/contact person at ImmoScout24</span></p></li></ul>"
        ]
      },
