          "<p class=\"hf-rich--custom3\"><span class=\"hf-rich--bold\">Seeker</span></p>",
          "<p class=\"hf-rich--body\">You can incorporate all vibrant brand colours to create cohesive visual identity.</p>",
          "<h4 class=\"hf-rich--heading4\"><span class=\"hf-rich--bold\">Homeowner</span> </h4>",
