      "14": {
        "rich": [
          "<h3 class=\"hf-rich--heading3\">Advanced illustrations</h3>"
        ]
      },
      "15": {
        "rich": [
          "<p class=\"hf-rich--body\">Illustrations can play a role in our storytelling — especially when we want to create emotional resonance in large formats like headers or posters.<br>While we’ve moved away from handcrafted, analog artwork toward a more simplified and digital-first approach, select expressive visuals are still available for special use cases. These are carefully designed to align with our current visual identity and are best suited for moments where storytelling needs more depth.</p>"
        ]
      },
