            "rich": [
              "<p class=\"hf-rich--custom3\"><span class=\"hf-rich--bold\">Lightness with depth</span></p>",
              "<p class=\"hf-rich--body\">We’re not naive. We know moving, buying, and selling homes can be challenging. But we show people not at the beginning of their problem – we show them finding a way forward.</p><p class=\"hf-rich--body\"></p>"
            ]
