      "15": {},
      "16": {
        "rich": [
          "<p class=\"hf-rich--custom3\"><span class=\"hf-rich--bold\">Wir setzen auf emotionale Überzeugung statt harter Verkaufsmethoden. Unsere Kommunikation …</span></p><p class=\"hf-rich--body\"></p><p class=\"hf-rich--body\">•  … schafft emotionale Verbindung.</p><p class=\"hf-rich--body\">•  … baut auf dem auf, was wir tun.</p><p class=\"hf-rich--body\">•  … zeigt, was ImmoScout24 für Menschen bedeutet.</p>"
        ]
      },
      "17": {},
