        "rich": [
          "<p class=\"hf-rich--body\">We know our strengths and communicate with conviction. Confident, but never arrogant.</p>",
          "<p class=\"hf-rich--body\">We speak in a human and approachable way. Our communication feels like a conversation on equal terms.</p>",
          "<p class=\"hf-rich--body\">We are solution-oriented and convey a positive attitude. Our enthusiasm inspires customer excitement.</p>",
          "<p class=\"hf-rich--body\">We avoid marketing clichés and jargon. We speak like real people and make complex things simple.</p>"
        ],
