        "rich": [
          "<p class=\"hf-rich--custom3\"><span class=\"hf-rich--bold\">We focus on emotional persuasion instead of hard selling methods. Our communication:</span></p><p class=\"hf-rich--body\">•  … creates emotional connection.</p><p class=\"hf-rich--body\">•  … builds on what we do.</p><p class=\"hf-rich--body\">•  … shows what ImmoScout24 means to people.</p>"
        ]
